send-one-way-request.set-body:
@{
          var respBody = context.Response.Body.As(preserveContent: true);
          var classification = (JObject)context.Variables["classificationResult"];
          var action = classification["action"].ToString();
          var choices = (JArray)respBody["choices"];
          var responseText = choices.Count > 0 ? (string)choices[0]["message"]["content"] : "";
          var usage = respBody["usage"];
          var promptTokens = usage != null ? (int)usage["prompt_tokens"] : 0;
          var completionTokens = usage != null ? (int)usage["completion_tokens"] : 0;
          var modelName = respBody["model"] != null ? (string)respBody["model"] : "gpt-4o-mini";
          var latencyMs = (int)context.Elapsed.TotalMilliseconds;

          var payload = new JObject(
              new JProperty("prompt", (string)context.Variables["promptText"]),
              new JProperty("response", responseText),
              new JProperty("classification", classification["classification"]),
              new JProperty("action", action),
              new JProperty("triggered_rule", classification["triggered_rule"]),
              new JProperty("model", modelName),
              new JProperty("prompt_tokens", promptTokens),
              new JProperty("completion_tokens", completionTokens),
              new JProperty("latency_ms", latencyMs)
          );
          return payload.ToString();
      }
